declare
  v_cohort_name text;
  v_audience broadcast_audience;
  v_conversation_id uuid;
begin
  select name into v_cohort_name from cohorts where id = p_cohort_id;
 
  foreach v_audience in array array['everyone','mentors','mentees']::broadcast_audience[]
  loop
    select id into v_conversation_id from conversations
      where cohort_id = p_cohort_id and kind = 'broadcast' and audience = v_audience;
 
    if v_conversation_id is null then
      insert into conversations (kind, cohort_id, audience, created_by, name)
      values ('broadcast', p_cohort_id, v_audience, p_created_by,
              v_cohort_name || ' — ' || initcap(v_audience::text))
      returning id into v_conversation_id;
 
      -- backfill every current PM/associate as a full sender on the new channel
      insert into conversation_participants (conversation_id, user_id, can_message)
      select v_conversation_id, u.id, true
      from users u where u.role in ('pm', 'associate');
    end if;
  end loop;
end;

declare
  v_pod_conversation_id uuid;
  v_cohort_id uuid;
  v_user_role user_role;
begin
  select cohort_id into v_cohort_id from pods where id = new.pod_id;
  select role into v_user_role from users where id = new.user_id;
 
  -- Pod conversation: create if needed, join always
  select id into v_pod_conversation_id from conversations
    where pod_id = new.pod_id and kind = 'pod';
  if v_pod_conversation_id is null then
    insert into conversations (kind, pod_id, cohort_id, created_by, name)
    select 'pod', p.id, p.cohort_id, new.user_id, p.name from pods p where p.id = new.pod_id
    returning id into v_pod_conversation_id;
  end if;
  insert into conversation_participants (conversation_id, user_id, can_message)
  values (v_pod_conversation_id, new.user_id, true)
  on conflict (conversation_id, user_id) do update set left_at = null;
 
  -- Cohort broadcasts: ensure they exist, then join the ones this role receives
  perform ensure_cohort_broadcasts(v_cohort_id, new.user_id);
 
  insert into conversation_participants (conversation_id, user_id, can_message)
  select c.id, new.user_id,
    (c.audience = 'mentors' and v_user_role = 'mentor')  -- only reply-capable case
  from conversations c
  where c.kind = 'broadcast' and c.cohort_id = v_cohort_id
    and (
      c.audience = 'everyone'
      or (c.audience = 'mentors' and v_user_role = 'mentor')
      or (c.audience = 'mentees' and v_user_role = 'mentee')
    )
  on conflict (conversation_id, user_id) do update set left_at = null;
 
  return new;
end;

DECLARE
  v_user_id uuid := auth.uid();
  v_message public.messages;
BEGIN
  IF v_user_id IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  IF NOT public.is_staff(v_user_id) THEN
    RAISE EXCEPTION 'Only associate/program_manager roles may enter conversations via this path';
  END IF;

  -- Insert or reactivate participant row.
  INSERT INTO public.conversation_participants (conversation_id, user_id, can_message, left_at)
  VALUES (p_conversation_id, v_user_id, true, NULL)
  ON CONFLICT (conversation_id, user_id)
  DO UPDATE SET can_message = true, left_at = NULL;

  -- If no body was provided, this was a plain "Enter" click — return early.
  IF p_body IS NULL OR btrim(p_body) = '' THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.messages (conversation_id, sender_id, body, client_generated_id)
  VALUES (p_conversation_id, v_user_id, p_body, p_client_generated_id)
  RETURNING * INTO v_message;

  RETURN v_message;
END;

SELECT EXISTS (
  SELECT 1
  FROM public.users u
  WHERE u.id = check_user_id
    AND u.role IN ('associate', 'pm')
);

BEGIN
  IF NEW.last_read_at IS NULL THEN
    RETURN NEW;
  END IF;
  IF OLD.last_read_at IS NOT NULL AND NEW.last_read_at <= OLD.last_read_at THEN
    RETURN NEW;
  END IF;

  UPDATE public.user_notifications un
  SET read_at = now()
  FROM public.notifications n
  JOIN public.messages m ON m.id = n.message_id
  WHERE un.notification_id = n.id
    AND un.user_id = NEW.user_id
    AND m.conversation_id = NEW.conversation_id
    AND m.created_at <= NEW.last_read_at
    AND un.read_at IS NULL;

  RETURN NEW;
END;

